{
  "sql": "SELECT COALESCE(t.product_category_name_english, 'sin_categoria') AS categoria, ROUND(SUM(f.freight_value) * 100.0 / SUM(f.price), 2) AS porcentaje_flete FROM vw_ingresos_por_categoria c JOIN order_items f ON c.categoria_ingles = f.product_category_name LEFT JOIN product_category_translation t ON t.product_category_name = c.categoria_ingles WHERE c.ingresos >= 5000 ORDER BY porcentaje_flete DESC LIMIT 3"
}
